const __pageData = JSON.parse('{"title":"11. Economic operators, conformity and market surveillance","description":"","frontmatter":{},"headers":[],"relativePath":"11-economic-operators-and-conformity.md","filePath":"11-economic-operators-and-conformity.md"}');
